const program14 = {
  id: 14,
  title: "Program 14 - Array Sum",
  lang: "c",
  code: `#include <stdio.h>

int main() {
    int n;
    printf("Enter n: ");
    scanf("%d", &n);
    int arr[n];
    int sum = 0;
    for (int i=0;i<n;i++){
        scanf("%d", &arr[i]);
        sum += arr[i];
    }
    printf("Sum = %d\\n", sum);
    return 0;
}
`
};

export default program14;
